// Wallet "Add to..." badges inlined as data URIs so they render without a
// network fetch (like the data-URI card logo) — bypasses cache / content-blocker
// / network issues that can break the external badge files on some devices.
export const APPLE_WALLET_BADGE = "data:image/png;base64,";
export const GOOGLE_WALLET_BADGE = "data:image/svg+xml;base64,";
